-- 脱敏规则模板及用户管理入库、出库策略。
-- 表结构由 GORM AutoMigrate 根据生成模型创建，本文件只初始化固定模板和运行时策略。

SET NAMES utf8mb4;
SET @old_foreign_key_checks = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

-- base_redact_storage_policy：用户表主表保存脱敏值，旁表保存加密原文和精确查询摘要。

-- base_redact_output_policy：用户列表、分页和详情接口按 operation 精确匹配出库规则。

SET FOREIGN_KEY_CHECKS = @old_foreign_key_checks;
